export function jiraSite(value){const u=new URL(value);if(u.protocol!=='https:'||!/^[-a-z0-9]+\.atlassian\.net$/i.test(u.hostname)||u.port||u.username||u.password||u.search||u.hash||u.pathname!=='/')throw Error('Enter a Jira Cloud origin such as https://your-team.atlassian.net');return u.origin;}
export function jiraText(value,depth=0){if(depth>20)return '';if(typeof value==='string')return value;if(!value||typeof value!=='object')return '';if(value.type==='text')return String(value.text||'');if(value.type==='hardBreak')return '\n';return (value.content||[]).map(v=>jiraText(v,depth+1)).join(['doc','bulletList','orderedList','listItem'].includes(value.type)?'\n':'')+(value.type==='paragraph'?'\n':'');}
export function jiraAdf(text){return{type:'doc',version:1,content:String(text).split('\n').map(line=>({type:'paragraph',content:line?[{type:'text',text:line}]:[]}))};}
export function jiraStory(issue,site,sprintId){if(!/^[A-Z][A-Z0-9_]*-\d+$/i.test(issue.key))throw Error('Invalid Jira issue key.');site=jiraSite(site);const f=issue.fields||{};return{id:crypto.randomUUID(),revision:1,title:`${issue.key}: ${String(f.summary||'Untitled').slice(0,450)}`,criteria:'Imported Jira description — review and refine acceptance criteria:\n'+jiraText(f.description).slice(0,11000),examples:'',risks:'',questions:'Clarify acceptance examples and testing risks with the team.',priority:'Medium',status:'Planned',reviewer:'',decision:'',jira:{site,key:issue.key,sprintId:String(sprintId),updated:String(f.updated||''),status:String(f.status?.name||''),type:String(f.issuetype?.name||'')}};}
export function jiraEvidence(story,session,sprint){return{format:'ReleaseRadar session evidence v1',generatedAt:new Date().toISOString(),sprint:{name:sprint.name,goal:sprint.goal},story:{title:story.title,revision:story.revision,criteria:story.criteria,risks:story.risks,jira:story.jira||null},session:{charter:session.charter,storyRevision:session.revision,state:session.state,oracle:session.oracle,coverage:session.coverage,notes:session.notes,debrief:session.debrief,next:session.next},limitations:'Session notes and check summaries are supporting evidence. This report does not prove complete coverage or approve release.'};}
